mapper.select:
SELECT *, operation_id::text AS operation_id, result_json::text AS result_json
FROM public.nocode_document_receipt
WHERE creator = #{actor}
AND application_id IS NOT DISTINCT FROM CAST(#{app} AS bigint)
AND object_id = CAST(#{object} AS bigint)
AND operation = #{operation}
AND request_key = #{key}
AND deleted = 0
